class Calculadora:
    def __init__(self):
        self.valor = 0

    def sumar(self, n):
        self.valor += n

    def restar(self, n):
        self.valor -= n

    def multiplicar(self, n):
        self.valor *= n

    def dividir(self, n):
        if n != 0:
            self.valor /= n
        else:
            print("Error: división por cero")

    def resultado(self):
        return self.valor

# Prueba
calc = Calculadora()
calc.sumar(10)
calc.multiplicar(2)
calc.restar(5)
print(calc.resultado())  # 15

