class Temperatura:
    def __init__(self, celsius):
        self._celsius = celsius

    @property
    def celsius(self):
        return self._celsius

    @celsius.setter
    def celsius(self, valor):
        if valor < -273.15:
            raise ValueError("Temperatura imposible")
        self._celsius = valor

    @property
    def fahrenheit(self):
        return (self._celsius * 9/5) + 32

t = Temperatura(25)
print(t.celsius)      # 25
print(t.fahrenheit)    # 77.0
t.celsius = 30
print(t.fahrenheit)    # 86.0

