class Configuracion:
    def __init__(self, config_dict):
        self.config = config_dict
        self._validar_requeridos(['host', 'puerto', 'usuario'])

    def _validar_requeridos(self, requeridos):
        for clave in requeridos:
            if clave not in self.config:
                raise ValueError(f"Falta clave requerida: {clave}")

# Prueba
