class Semaforo:
    def __init__(self):
        self.estado = "rojo"  # Estado inicial

    def cambiar(self):
        """Cambia el estado del semáforo"""
        if self.estado == "rojo":
            self.estado = "verde"
        elif self.estado == "verde":
            self.estado = "amarillo"
        else:
            self.estado = "rojo"

    def puede_pasar(self):
        """Comportamiento basado en estado"""
        return self.estado == "verde"

s = Semaforo()
print(s.puede_pasar())  # False
s.cambiar()
print(s.puede_pasar())  # True

class JuegoAdivinanza:
    def __init__(self, numero_secreto):
        self.numero_secreto = numero_secreto
        self.intentos = 0
        self.terminado = False

    def adivinar(self, numero):
        if self.terminado:
            return "El juego ya terminó"

        self.intentos += 1

        if numero == self.numero_secreto:
            self.terminado = True
            return f"¡Correcto! Lo adivinaste en {self.intentos} intentos"
        elif numero < self.numero_secreto:
            return "Más alto"
        else:
            return "Más bajo"

juego = JuegoAdivinanza(50)
print(juego.adivinar(30))  # Más alto
print(juego.adivinar(70))  # Más bajo
print(juego.adivinar(50))  # ¡Correcto! Lo adivinaste en 3 intentos

