class CarritoCompras:
    def __init__(self):
        self.items = []
        self._total = 0

    def agregar(self, item, precio):
        self.items.append((item, precio))
        self._total += precio

    def eliminar(self, indice):
        if 0 <= indice < len(self.items):
            item, precio = self.items.pop(indice)
            self._total -= precio

    def vaciar(self):
        self.items = []
        self._total = 0

    def obtener_total(self):
        return self._total

carrito = CarritoCompras()
carrito.agregar("Laptop", 999.99)
carrito.agregar("Mouse", 25.50)
print(carrito.obtener_total())  # 1025.49

class JuegoLaberinto:
    def __init__(self):
        self.posicion_actual = (0, 0)
        self.tiene_llave = False
        self.juego_terminado = False

    def mover(self, direccion):
        if self.juego_terminado:
            return "Juego terminado"

        x, y = self.posicion_actual
        if direccion == "arriba":
            self.posicion_actual = (x, y + 1)
        elif direccion == "abajo":
            self.posicion_actual = (x, y - 1)
        # ... otras direcciones
        return f"Movido a {self.posicion_actual}"

    def recoger_llave(self):
        self.tiene_llave = True
        return "¡Has recogido la llave!"

    def salir(self):
        if self.tiene_llave:
            self.juego_terminado = True
            return "¡Has escapado!"
        return "Necesitas la llave"

class ContadorLimitado:
    def __init__(self, maximo=10):
        self.valor = 0
        self.maximo = maximo

    def incrementar(self):
        if self.valor < self.maximo:
            self.valor += 1
            return self.valor
        return "Máximo alcanzado"

    def decrementar(self):
        if self.valor > 0:
            self.valor -= 1
            return self.valor
        return "Mínimo alcanzado"

    def reiniciar(self):
        self.valor = 0
        return self.valor

c = ContadorLimitado(5)
print(c.incrementar())  # 1
print(c.incrementar())  # 2
